      body: msg.body,
      author: msg.author,
      runId,
    });
  }

  // Poll until search results are found
  let result;
  const maxAttempts = 60;
  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      result = await client.query("messages:search", {
        query: "Hello",
        runId,
        paginationOpts: { numItems: 2, cursor: null },
