      // swallow and retry
    }
    await sleep(1000);
  }

  if (!result || !Array.isArray(result.page)) {
    console.error("Search did not return results");
    process.exit(1);
  }

  console.log(JSON.stringify(result.page));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
